int min_jumps(vector<int> nums) {
    int jumps = 0, end = 0, farthest = 0;
    for (int i = 0; i + 1 < (int)nums.size(); ++i) {
        farthest = max(farthest, i + nums[i]);
        if (i == end) {
            ++jumps;
            end = farthest;
        }
    }
    return jumps;
}

